def pancake_sort(arr):
    def flip(arr, k):
        left = 0
        while left < k:
            arr[left], arr[k] = arr[k], arr[left]
            left += 1
            k -= 1

    n = len(arr)
    while n > 1:
        max_idx = 0
        for i in range(1, n):
            if arr[i] > arr[max_idx]:
                max_idx = i

        if max_idx != n - 1:
            if max_idx != 0:
                flip(arr, max_idx)
            flip(arr, n - 1)
        n -= 1
    return arr

