def max_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    # Initialize arrays to store maximum increasing and decreasing sums
    inc = [0] * n
    dec = [0] * n

    # Fill inc array: maximum sum ending at each index with increasing sequence
    for i in range(n):
        inc[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i]:
                inc[i] = max(inc[i], inc[j] + arr[i])

    # Fill dec array: maximum sum starting at each index with decreasing sequence
    for i in range(n-1, -1, -1):
        dec[i] = arr[i]
        for j in range(i+1, n):
            if arr[j] < arr[i]:
                dec[i] = max(dec[i], dec[j] + arr[i])

    # Find maximum sum of bitonic subsequence
    max_sum_bitonic = 0
    for i in range(n):
        # The bitonic sequence has peak at i
        # Sum = increasing part + decreasing part - arr[i] (counted twice)
        bitonic_sum = inc[i] + dec[i] - arr[i]
        max_sum_bitonic = max(max_sum_bitonic, bitonic_sum)

    return max_sum_bitonic

