def max_sum_increasing_subseq(arr, n, i, k):
    if i >= k or k >= n:
        return 0

    # dp[i] stores the maximum sum of increasing subsequence ending at index i
    dp = [0] * n
    for idx in range(n):
        dp[idx] = arr[idx]

    # Fill dp array for indices from 0 to i
    for idx in range(1, i + 1):
        for j in range(idx):
            if arr[j] < arr[idx]:
                dp[idx] = max(dp[idx], dp[j] + arr[idx])

    # Now find maximum sum ending at or before i, and then include arr[k]
    max_sum_before_i = max(dp[:i + 1])

    # Check if we can extend the subsequence to include arr[k]
    result = max_sum_before_i
    for j in range(i + 1):
        if arr[j] < arr[k]:
            result = max(result, dp[j] + arr[k])

    return result

