def set_left_most_unset_bit(n):
    if n == 0:
        return 1
    bit_pos = 0
    temp = n
    while temp > 0:
        if (temp & 1) == 0:
            break
        temp >>= 1
        bit_pos += 1
    return n | (1 << bit_pos)

