def sumofFactors(n):
    result = 0
    i = 2
    while i * i <= n:
        if n % i == 0:
            if i % 2 == 0:
                result += i
            if i != n // i and (n // i) % 2 == 0:
                result += n // i
        i += 1
    if n % 2 == 0:
        result += n
    return result

