def find_kth(arr1, arr2, k):
    if len(arr1) == 0:
        return arr2[k - 1]
    if len(arr2) == 0:
        return arr1[k - 1]

    if k == 1:
        return min(arr1[0], arr2[0])

    mid1 = min(k // 2, len(arr1))
    mid2 = min(k // 2, len(arr2))

    if arr1[mid1 - 1] < arr2[mid2 - 1]:
        return find_kth(arr1[mid1:], arr2, k - mid1)
    else:
        return find_kth(arr1, arr2[mid2:], k - mid2)

