def get_ludic(n):
    if n < 1:
        return []
    ludic = list(range(1, n + 1))
    index = 1
    while index < len(ludic):
        step = ludic[index]
        ludic = [ludic[i] for i in range(len(ludic)) if i == 0 or (i - 1) % step != 0]
        index += 1
    return ludic

