def sum_Of_Subarray_Prod(lst):
    if not lst:
        return 0
    n = len(lst)
    total_sum = 0
    for i in range(n):
        for j in range(i, n):
            product = 1
            for k in range(i, j + 1):
                product *= lst[k]
            total_sum += product
    return total_sum

