def is_decimal(s):
    try:
        parts = s.split('.')
        if len(parts) != 2:
            return False
        integer_part, decimal_part = parts
        if not integer_part and not decimal_part:
            return False
        if not integer_part.isdigit() or not decimal_part.isdigit():
            return False
        if len(decimal_part) > 2:
            return False
        return True
    except:
        return False

