def get_pairs_count(nums, target):
    from collections import Counter
    count = Counter(nums)
    pairs = 0
    for num in count:
        complement = target - num
        if complement in count:
            if num == complement:
                pairs += count[num] * (count[num] - 1) // 2
            else:
                pairs += count[num] * count[complement]
    return pairs // 2

